examples.template:
MonarchButton({{trigger}}) { isAsking = true }
    .monarchDialog(isPresented: $isAsking, title: {{title}}, message: {{description}}) {
        MonarchTextField({{label}}, text: $name, prompt: {{placeholder}}, isRequired: true)
            .onChange(of: name) { _, new in name = String(new.prefix({{maxLength}})) }
    } footer: {
        HStack(spacing: 8) {
            MonarchButton("Cancel") { isAsking = false }
            MonarchButton({{submitLabel}}, variant: .primary) {
                name = name.trimmingCharacters(in: .whitespacesAndNewlines)
                isAsking = false
            }
        }
    }

examples.code:
MonarchButton("Save view as") { isAsking = true }
    .monarchDialog(isPresented: $isAsking, title: "Name this view", message: "Saved views appear in the sidebar.") {
