examples.setup:
@Environment(\.monarchTheme) private var theme
@State private var isAsking = false
@State private var link = ""
@State private var error: String?

examples.code:
MonarchButton("Add a link") { isAsking = true }
    .sheet(isPresented: $isAsking) {
        VStack(alignment: .leading, spacing: theme.spacing.space4) {
            Text("Add a link").monarchTextStyle(.heading)
            MonarchTextField("Address", text: $link, prompt: "https://", error: error)
            MonarchButton("Add", variant: .primary, fullWidth: true) {
                if URL(string: link)?.scheme == "https" {
                    isAsking = false
                } else {
                    error = "Enter a full web address, starting with https://."
                }
            }
            MonarchButton("Cancel", variant: .ghost, fullWidth: true) { isAsking = false }
        }
        .foregroundStyle(theme.colors.textDefault)
        .padding(theme.spacing.space4)
        .presentationDetents([.medium])
    }
